PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_total NUMBER := 0;
BEGIN
    SELECT COUNT(*)
      INTO l_total
      FROM @@tab@@
     WHERE @@col@@ = p_id;

    UPDATE @@tab2@@
       SET @@col2@@ = l_total
     WHERE @@col@@ = p_id;
EXCEPTION
    WHEN OTHERS THEN -- @expect
        -- nothing sensible can be done here
        NULL;
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_failed BOOLEAN := FALSE;
    l_ratio  NUMBER;
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        BEGIN
            l_ratio := 100 / p_ids(i);
            @@proc2@@(p_ids(i), l_ratio);
        EXCEPTION
            WHEN OTHERS THEN -- @expect
                l_failed := TRUE;
                CONTINUE;
        END;
    END LOOP;
    IF l_failed THEN
        DBMS_OUTPUT.PUT_LINE('some rows were skipped');
    END IF;
END @@proc@@;

FUNCTION @@proc@@ (p_a IN NUMBER, p_b IN NUMBER) RETURN VARCHAR2 IS
    l_ratio NUMBER;
BEGIN
    l_ratio := p_a / p_b;
    RETURN CASE
               WHEN l_ratio > 1 THEN 'Y'
               ELSE 'N'
           END;
EXCEPTION
    WHEN OTHERS THEN -- @expect
        RETURN 'N';
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER, p_amount IN NUMBER) IS
BEGIN
    INSERT INTO @@tab@@ (@@col@@, @@col2@@)
    VALUES (p_id, p_amount);

    UPDATE @@tab2@@
       SET @@col2@@ = @@col2@@ + p_amount
     WHERE @@col@@ = p_id;
EXCEPTION
    WHEN OTHERS THEN -- @expect
        ROLLBACK;
END @@proc@@;

PROCEDURE @@proc@@ (p_batch_id IN NUMBER) IS
    l_rows PLS_INTEGER;
BEGIN
    DELETE FROM @@tab@@
     WHERE batch_id = p_batch_id;
    l_rows := SQL%ROWCOUNT;

    UPDATE @@tab2@@
       SET status = 'DONE',
           row_count = l_rows
     WHERE batch_id = p_batch_id;
EXCEPTION
    WHEN OTHERS THEN -- @expect
        UPDATE @@tab2@@
           SET status = 'FAILED'
         WHERE batch_id = p_batch_id;
END @@proc@@;

