PROCEDURE @@proc@@ (p_dept IN NUMBER) IS
    CURSOR c_emp (p_d NUMBER) IS
        SELECT @@col@@, @@col2@@
          FROM @@tab@@
         WHERE dept_id = p_d;
    l_row c_emp%ROWTYPE;
BEGIN
    OPEN c_emp(p_dept);
    LOOP
        FETCH c_emp INTO l_row;
        EXIT WHEN c_emp%NOTFOUND;
        @@proc2@@(l_row.@@col@@);
    END LOOP;
    CLOSE c_emp;
EXCEPTION
    WHEN OTHERS THEN
        IF c_emp%ISOPEN THEN
            CLOSE c_emp;
        END IF;
        audit_pkg.write('@@str@@', p_dept);
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    my_error EXCEPTION;
    l_cnt    NUMBER;
BEGIN
    SELECT COUNT(*) INTO l_cnt FROM @@tab@@ WHERE @@col@@ = p_id;
    IF l_cnt = 0 THEN
        RAISE my_error;
    END IF;
    BEGIN
        UPDATE @@tab@@
           SET @@col2@@ = SYSDATE
         WHERE @@col@@ = p_id;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE my_error;
    END;
END @@proc@@;

PROCEDURE @@proc@@ (p_key IN VARCHAR2) IS
    l_id NUMBER;
BEGIN
    BEGIN
        SELECT id
          INTO l_id
          FROM @@tab@@
         WHERE @@col@@ = p_key;
    EXCEPTION
        WHEN TOO_MANY_ROWS THEN
            NULL;
    END;
    UPDATE @@tab2@@
       SET @@col2@@ = SYSDATE
     WHERE id = l_id;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER, p_ok OUT BOOLEAN, p_error OUT VARCHAR2) IS
BEGIN
    p_ok := TRUE;
    @@proc2@@(p_id);
    UPDATE @@tab@@
       SET @@col@@ = SYSDATE
     WHERE id = p_id;
EXCEPTION
    WHEN OTHERS THEN
        p_ok := FALSE;
        p_error := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
END @@proc@@;

FUNCTION @@proc@@ (p_text IN VARCHAR2, p_default IN DATE) RETURN DATE IS
    l_date DATE;
BEGIN
    IF p_text IS NULL THEN
        RETURN p_default;
    END IF;
    l_date := TO_DATE(p_text, 'YYYY-MM-DD');
    RETURN l_date;
EXCEPTION
    WHEN OTHERS THEN
        trace_pkg.add('unparseable date', p_text);
        RETURN p_default;
END @@proc@@;
